const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d=$input.first().json,p=d.person,start=new Date(p.startDate);
const date=(offset)=>new Date(start.getTime()+offset*86400000).toISOString().slice(0,10);
const tasks=[
{task:'Send welcome email and intake form',owner:'Client Success',due:date(-5)},
{task:'Create shared workspace and project record',owner:'Operations',due:date(-3)},
{task:'Confirm goals, systems, and access requirements',owner:'Solutions Architect',due:date(-1)},
{task:'Run kickoff meeting',owner:'Solutions Architect',due:date(0)},
{task:'Deliver first progress update',owner:'Project Lead',due:date(7)}
];
return [{json:{...d,result:{person:p,status:'onboarding_scheduled',tasks,welcomeMessage:`Welcome ${p.name}. We are excited to begin your ${p.package} onboarding.`,readiness:{taskCount:tasks.length,startDate:p.startDate},createdAt:new Date().toISOString()}}}];
